-- OWNER CONSOLE ONLY. meli-pu. Agent must NOT execute on production.
-- INSERT missing fr/nl/hr DRAFT translations only. Existing blank rows also win.
-- No announcements, no UPDATE/DELETE, no snapshot replacement, no publishing.
-- Source or legacy-language drift since preparation aborts the entire transaction.
-- Short table locks make checksum verification race-safe; execute one file at a time.
BEGIN;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '60s';
LOCK TABLE tenants, sections, categories, items, translations, published_snapshots IN SHARE ROW EXCLUSIVE MODE;
DO $rollout$
DECLARE before_state jsonb; after_state jsonb; inserted_count integer;
BEGIN
  SELECT evidence::jsonb INTO before_state FROM (-- Read-only. 'meli-pu' is one of the four approved production slugs.
WITH t AS (
  SELECT id, slug, name, subtitle, address, hero_url, living_guide_hero_url, logo_url
  FROM tenants WHERE slug = 'meli-pu'
), s AS (
  SELECT s.* FROM sections s JOIN t ON t.id=s.tenant_id WHERE s.deleted_at IS NULL
), c AS (
  SELECT c.* FROM categories c JOIN s ON s.id=c.section_id WHERE c.deleted_at IS NULL
), i AS (
  SELECT i.* FROM items i JOIN c ON c.id=i.category_id WHERE i.deleted_at IS NULL
), r AS (
  SELECT 'tenant' AS model,id FROM t UNION ALL SELECT 'section',id FROM s
  UNION ALL SELECT 'category',id FROM c UNION ALL SELECT 'item',id FROM i
), tr AS (
  SELECT tr.* FROM translations tr JOIN r ON r.model=tr.model AND r.id=tr.record_id
)
SELECT jsonb_build_object(
  'slug', 'meli-pu'::text,
  'source', md5(jsonb_build_object(
    'tenants',(SELECT jsonb_agg(t ORDER BY id) FROM t),
    'sections',(SELECT jsonb_agg(s ORDER BY id) FROM s),
    'categories',(SELECT jsonb_agg(c ORDER BY id) FROM c),
    'items',(SELECT jsonb_agg(i ORDER BY id) FROM i)
  )::text),
  'legacy', (SELECT jsonb_object_agg(lang, jsonb_build_object('count',n,'md5',digest))
    FROM (SELECT l.lang, count(tr.id) AS n,
      md5(COALESCE(jsonb_agg(to_jsonb(tr) ORDER BY tr.id)
        FILTER (WHERE tr.id IS NOT NULL),'[]'::jsonb)::text) AS digest
      FROM (VALUES ('sl'),('en'),('de'),('it')) l(lang)
      LEFT JOIN tr ON tr.lang=l.lang GROUP BY l.lang) q),
  'snapshot',(SELECT md5(p.content::text) FROM published_snapshots p JOIN t ON t.id=p.tenant_id),
  'snapshotPublishedAt',(SELECT p.published_at FROM published_snapshots p JOIN t ON t.id=p.tenant_id)
)::text AS evidence) evidence_query;
  IF before_state IS DISTINCT FROM '{"slug":"meli-pu","legacy":{"de":{"md5":"6639da12f3abcbd81a88f56c27536cea","count":319},"en":{"md5":"ee375855963f8822ce894d387caf1b30","count":319},"it":{"md5":"0757f4b6b6b7c81c01384b6dc7a4ef09","count":319},"sl":{"md5":"d751713988987e9331980363e24189ce","count":0}},"source":"f720aac9c9afc8caf977936e233c9241","snapshot":"76e458bdd697fe1c698b99953eef3fe2","snapshotPublishedAt":"2026-10-02T04:17:00.131+00:00"}'::jsonb THEN
    RAISE EXCEPTION 'Source, sl/en/de/it or published snapshot changed since preparation. Regenerate this tenant SQL; nothing inserted.';
  END IF;
