ue":"hoogwaardig geluidssysteem"},{"model":"item","record_id":"a1b3f0a4-4d72-4698-ae00-2c975cad3d09","field":"bullets[6]","lang":"hr","value":"vrhunski zvučni sustav"},{"model":"item","record_id":"6856f026-65cc-40c2-8b50-b76bb5d43037","field":"title","lang":"fr","value":"Zlatoperka : Ankaran → Koper"},{"model":"item","record_id":"6856f026-65cc-40c2-8b50-b76bb5d43037","field":"title","lang":"nl","value":"Zlatoperka: Ankaran → Koper"},{"model":"item","record_id":"6856f026-65cc-40c2-8b50-b76bb5d43037","field":"title","lang":"hr","value":"Zlatoperka: Ankaran → Koper"},{"model":"item","record_id":"6856f026-65cc-40c2-8b50-b76bb5d43037","field":"priceUnit","lang":"fr","value":"personne"},{"model":"item","record_id":"6856f026-65cc-40c2-8b50-b76bb5d43037","field":"priceUnit","lang":"nl","value":"persoon"},{"model":"item","record_id":"6856f026-65cc-40c2-8b50-b76bb5d43037","field":"priceUnit","lang":"hr","value":"osoba"},{"model":"item","record_id":"6856f026-65cc-40c2-8b50-b76bb5d43037","field":"bullets[0]","lang":"fr","value":"les billets s’achètent à bord avant le départ"},{"model":"item","record_id":"6856f026-65cc-40c2-8b50-b76bb5d43037","field":"bullets[0]","lang":"nl","value":"tickets koop je aan boord vóór vertrek"},{"model":"item","record_id":"6856f026-65cc-40c2-8b50-b76bb5d43037","field":"bullets[0]","lang":"hr","value":"karte se kupuju na brodu prije polaska"},{"model":"item","record_id":"6856f026-65cc-40c2-8b50-b76bb5d43037","field":"bullets[1]","lang":"fr","value":"les réservations ne sont pas possibles"},{"model":"item","record_id":"6856f026-65cc-40c2-8b50-b76bb5d43037","field":"bullets[1]","lang":"nl","value":"reserveren is niet mogelijk"},{"model":"item","record_id":"6856f026-65cc-40c2-8b50-b76bb5d43037","field":"bullets[1]","lang":"hr","value":"rezervacije nisu moguće"},{"model":"item","record_id":"6856f026-65cc-40c2-8b50-b76bb5d43037","field":"bullets[2]","lang":"fr","value":"places selon l’ordre d’arrivée"},{"model":"item","record_id":"6856f026-65cc-40c2-8b50-